import pathlib, tempfile, subprocess, shutil, json, os
trial=pathlib.Path('/app/taskfiles/trials/codex/ss007-pep752-implicit-namespaces__9pgMNNM/steps/1_pep752')
repo=trial/'artifacts/app'
commands=('curl','wget','ssh','scp','sftp','ftp','lftp','telnet','nc','ncat','socat','httpx')
with tempfile.TemporaryDirectory(prefix='review-pep752-') as td:
 root=pathlib.Path(td); bins=root/'bin';bins.mkdir();log=root/'network.log';log.touch()
 for command in commands:
  p=bins/command;p.write_text('#!/bin/sh\nprintf "%s\\n" "$0" >> "$PEP752_NETWORK_LOG"\nexit 1\n');p.chmod(0o755)
 env=dict(os.environ, PATH=str(bins)+os.pathsep+os.environ['PATH'],PEP752_NETWORK_LOG=str(log),PYTHON='/usr/bin/python3')
 for kind in ('original','scripts_only','full_tools'):
  if kind=='original':tools=repo/'Tools/packagenamespaces'
  else:
   mirror=root/kind;tools=mirror/'Tools/packagenamespaces';tools.parent.mkdir(parents=True)
   (mirror/'Lib').symlink_to(repo/'Lib',target_is_directory=True)
   if kind=='full_tools':shutil.copytree(repo/'Tools/packagenamespaces',tools)
   else:
    tools.mkdir()
    for name in ('gen_fixtures.sh','verify_offline.sh'): shutil.copy2(repo/'Tools/packagenamespaces'/name,tools/name)
   for name in ('gen_fixtures.sh','verify_offline.sh'):
    with (tools/name).open('a') as f:f.write('\n# '+' '.join(commands)+' urllib http.client\n')
  fixtures=root/(kind+'-fixtures');fixtures.mkdir()
  for name in ('gen_fixtures.sh','verify_offline.sh'):
   p=subprocess.run(['bash',str(tools/name),str(fixtures)],capture_output=True,text=True,cwd='/',env=env)
   print(json.dumps({'variant':kind,'script':name,'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr}))
 print('network command log:',repr(log.read_text()))
PY",max_output_tokens:3000}));

